// ─── HELPERS ──────────────────────────────────────────────────────────────────
function today(){ return new Date().toLocaleDateString("fr-FR",{day:"2-digit",month:"2-digit",year:"2-digit"}); }

function Av({initials,size=42,coach=false}){
  const pal={J:"184,212,0",C:"80,160,255",A:"255,144,80",L:"192,80,255",P:"80,255,208",S:"255,80,160"};
  const rgb=pal[initials[0]]||"184,212,0";
  if(coach) return (
    <div style={{width:size,height:size,borderRadius:size*.28,background:"#0d0d0d",border:"1.5px solid rgba(184,212,0,.3)",display:"flex",alignItems:"center",justifyContent:"center",overflow:"hidden",padding:3,flexShrink:0}}>
      <img src={LOGO} alt="Coach" style={{width:"100%",height:"100%",objectFit:"contain"}}/>
    </div>
  );
  return <div style={{width:size,height:size,borderRadius:size*.28,background:`rgba(${rgb},.12)`,border:`1.5px solid rgba(${rgb},.28)`,display:"flex",alignItems:"center",justifyContent:"center",fontFamily:"'Bebas Neue'",fontSize:size*.33,color:`rgb(${rgb})`,flexShrink:0}}>{initials}</div>;
}

function PBar({value,h=5,color}){
  return <div className="pb2" style={{height:h}}><div className="pb2f" style={{width:`${Math.min(100,value||0)}%`,background:color||undefined}}/></div>;
}

function Ring({value,size=68,stroke=6}){
  const r=(size-stroke)/2,c=2*Math.PI*r,d=(value/100)*c;
  return <svg width={size} height={size} style={{transform:"rotate(-90deg)"}}>
    <circle cx={size/2} cy={size/2} r={r} fill="none" stroke="#1a1a1a" strokeWidth={stroke}/>
    <circle cx={size/2} cy={size/2} r={r} fill="none" stroke="#B8D400" strokeWidth={stroke} strokeDasharray={`${d} ${c}`} strokeLinecap="round" style={{transition:"stroke-dasharray .9s ease"}}/>
  </svg>;
}

function StatutPay({statut,onClick}){
  const m={"payé":{bg:"rgba(184,212,0,.1)",color:"#B8D400",border:"rgba(184,212,0,.2)",icon:"✅"},"en attente":{bg:"rgba(255,160,50,.1)",color:"#ffa032",border:"rgba(255,160,50,.2)",icon:"⏳"},"impayé":{bg:"rgba(255,68,68,.1)",color:"#ff4444",border:"rgba(255,68,68,.2)",icon:"❌"}};
  const s=m[statut]||m["en attente"];
  return <span className="stt" onClick={onClick} style={{background:s.bg,color:s.color,border:`1px solid ${s.border}`}}>{s.icon} {statut}</span>;
}

function clientStats(c){
  const faites=c.seances.filter(s=>s.statut==="faite").length;
  const dues=c.seances.filter(s=>s.statut==="due").length;
  const rattrapees=c.seances.filter(s=>s.statut==="rattrapee").length;
  const parCoach=c.seances.filter(s=>s.statut==="coach").length;
  const restantes=Math.max(0,c.pack-(faites+rattrapees));
  const revenu=faites*c.tarif;
  const aRecouvrer=dues*c.tarif;
  const pct=c.pack>0?Math.min(100,Math.round(((faites+rattrapees)/c.pack)*100)):0;
  return{faites,dues,rattrapees,parCoach,restantes,revenu,aRecouvrer,pct};
}

// ─── DASHBOARD ────────────────────────────────────────────────────────────────
function Dashboard({clients,msgs,setScreen}){
  const totalMRR=clients.reduce((s,c)=>s+getOffre(c.offre).prix,0);
  const totalPaye=clients.reduce((s,c)=>s+c.paiements.filter(p=>p.statut==="payé").reduce((a,p)=>a+p.montant,0),0);
  const totalImpaye=clients.reduce((s,c)=>s+c.paiements.filter(p=>p.statut==="impayé").reduce((a,p)=>a+p.montant,0),0);
  const unread=msgs.filter(m=>!m.lu).length;
  const presClients=clients.filter(c=>c.type==="presentiel");
  const ligneClients=clients.filter(c=>c.type==="enligne");

  return <div style={{padding:"0 16px 16px",display:"flex",flexDirection:"column",gap:13}} className="fu">

    {/* Hero KPIs */}
    <div className="card" style={{background:"linear-gradient(140deg,#111,#141a00)"}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:14}}>
        <div>
          <div style={{fontSize:10,color:"#3a3a3a",textTransform:"uppercase",letterSpacing:.5,marginBottom:3}}>Revenus mensuels récurrents</div>
          <div style={{fontFamily:"'Bebas Neue'",fontSize:38,color:"#B8D400",lineHeight:1}}>{totalMRR}€<span style={{fontSize:14,color:"#444"}}>/mois</span></div>
          <div style={{fontSize:11,color:"#444",marginTop:3}}>Est. {totalMRR*12}€/an</div>
        </div>
        <div style={{textAlign:"right"}}>
          <div style={{fontFamily:"'Bebas Neue'",fontSize:22,color:"#B8D400"}}>{clients.length}</div>
          <div style={{fontSize:10,color:"#444"}}>clients actifs</div>
        </div>
      </div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:8}}>
        {[
          {l:"Encaissé",v:`${totalPaye}€`,c:"#B8D400"},
          {l:"Présentiel",v:`${presClients.length} clients`,c:"#50a0ff"},
          {l:"En ligne",v:`${ligneClients.length} clients`,c:"#ffa032"},
        ].map((s,i)=>(
          <div key={i} style={{background:"#0d0d0d",borderRadius:11,padding:"10px 8px",textAlign:"center",border:"1px solid #1a1a1a"}}>
            <div style={{fontFamily:"'Bebas Neue'",fontSize:16,color:s.c,lineHeight:1}}>{s.v}</div>
            <div style={{fontSize:9,color:"#333",marginTop:3,textTransform:"uppercase",letterSpacing:.3}}>{s.l}</div>
          </div>
        ))}
      </div>
    </div>

    {/* Alertes */}
    {(totalImpaye>0 || clients.some(c=>clientStats(c).dues>0)) && (
      <div style={{background:"rgba(255,68,68,.06)",border:"1px solid rgba(255,68,68,.18)",borderRadius:16,padding:"12px 15px"}}>
        <div style={{fontWeight:700,fontSize:13,color:"#ff4444",marginBottom:6}}>⚠️ Actions requises</div>
        {totalImpaye>0 && <div style={{fontSize:12,color:"#555",marginBottom:3}}>❌ {totalImpaye}€ de paiements impayés</div>}
        {clients.filter(c=>clientStats(c).dues>0).map(c=>(
          <div key={c.id} style={{fontSize:12,color:"#555"}}>🔴 {c.name} — {clientStats(c).dues} séance(s) due(s) ({clientStats(c).aRecouvrer}€)</div>
        ))}
      </div>
    )}

    {/* Raccourcis */}
    <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
      {[
        {icon:"👥",label:"Mes clients",sub:`${clients.length} actifs`,screen:"clients",c:"#B8D400"},
        {icon:"📋",label:"Séances",sub:"Suivi présentiel",screen:"seances",c:"#50a0ff"},
        {icon:"💰",label:"Paiements",sub:`MRR ${totalMRR}€`,screen:"paiements",c:"#ffa032"},
        {icon:"💬",label:"Messages",sub:unread>0?`${unread} non lus`:"Tout lu",screen:"messages",c:unread>0?"#ff4444":"#B8D400"},
      ].map((s,i)=>(
        <div key={i} className="card tap" onClick={()=>setScreen(s.screen)} style={{padding:"16px 15px"}}>
          <div style={{fontSize:24,marginBottom:8}}>{s.icon}</div>
          <div style={{fontFamily:"'Bebas Neue'",fontSize:17,letterSpacing:.8,marginBottom:2}}>{s.label}</div>
          <div style={{fontSize:11,color:s.c,fontWeight:600}}>{s.sub}</div>
        </div>
      ))}
    </div>

    {/* Clients récents */}
    <div className="card">
      <div className="st">MES CLIENTS</div>
      {clients.slice(0,4).map(c=>{
        const st=clientStats(c);
        const o=getOffre(c.offre);
        return (
          <div key={c.id} className="cr">
            <Av initials={c.avatar} size={42}/>
            <div style={{flex:1,minWidth:0}}>
              <div style={{display:"flex",alignItems:"center",gap:7,marginBottom:4}}>
                <span style={{fontWeight:700,fontSize:13}}>{c.name}</span>
                <span className={`pill ${c.type==="presentiel"?"pb":"pg"}`} style={{fontSize:8}}>{c.type==="presentiel"?"🏋️":"💻"}</span>
                {st.dues>0&&<span className="pill pr" style={{fontSize:8}}>🔴 {st.dues} due{st.dues>1?"s":""}</span>}
              </div>
              <div style={{fontSize:10,color:o.color}}>{o.emoji} {o.nom} · {o.prix}€/mois</div>
            </div>
            <div style={{textAlign:"right"}}>
              {c.type==="presentiel"&&<div style={{fontFamily:"'Bebas Neue'",fontSize:18,color:"#B8D400"}}>{st.faites+st.rattrapees}<span style={{fontSize:10,color:"#333"}}>/{c.pack}</span></div>}
              {c.type==="enligne"&&<div style={{fontFamily:"'Bebas Neue'",fontSize:16,color:"#B8D400"}}>{c.paiements.filter(p=>p.statut==="payé").length}<span style={{fontSize:10,color:"#333"}}> mois</span></div>}
            </div>
          </div>
        );
      })}
    </div>

    {/* Messages */}
    <div className="card">
      <div className="st">MESSAGES RÉCENTS</div>
      {msgs.slice(0,3).map(m=>(
        <div key={m.id} style={{display:"flex",alignItems:"center",gap:11,padding:"9px 0",borderBottom:"1px solid #161616"}}>
          <div style={{position:"relative"}}><Av initials={m.av} size={36}/>{!m.lu&&<div style={{position:"absolute",top:-2,right:-2,width:8,height:8,borderRadius:"50%",background:"#B8D400",border:"2px solid #111"}}/>}</div>
          <div style={{flex:1,minWidth:0}}>
            <div style={{display:"flex",justifyContent:"space-between"}}><span style={{fontWeight:700,fontSize:13}}>{m.from}</span><span style={{fontSize:10,color:"#333"}}>{m.time}</span></div>
            <div style={{fontSize:12,color:"#444",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{m.text}</div>
          </div>
        </div>
      ))}
    </div>
  </div>;
}

// ─── CLIENTS SCREEN ───────────────────────────────────────────────────────────
function ClientsScreen({clients,setClients}){
  const [sel,setSel]=useState(null);
  const [showNew,setShowNew]=useState(false);
  const [nc,setNc]=useState({name:"",goal:"",type:"presentiel",offre:"p_sport",tarif:"50",pack:"10"});

  const addClient=()=>{
    if(!nc.name) return;
    const id=Math.max(0,...clients.map(c=>c.id))+1;
    const av=nc.name.split(" ").map(w=>w[0]).join("").slice(0,2).toUpperCase();
    setClients(p=>[...p,{id,name:nc.name,avatar:av,goal:nc.goal||"Objectif à définir",type:nc.type,offre:nc.offre,tarif:Number(nc.tarif)||50,pack:Number(nc.pack)||10,seances:[],paiements:[]}]);
    setShowNew(false); setNc({name:"",goal:"",type:"presentiel",offre:"p_sport",tarif:"50",pack:"10"});
  };

  if(!sel) return <div style={{padding:"0 16px 16px",display:"flex",flexDirection:"column",gap:13}} className="fu">
    <div className="card">
      <div className="st">TOUS LES CLIENTS ({clients.length})</div>
      {clients.map(c=>{
        const st=clientStats(c); const o=getOffre(c.offre);
        return <div key={c.id} className="cr" onClick={()=>setSel(c.id)}>
          <Av initials={c.avatar} size={44}/>
          <div style={{flex:1,minWidth:0}}>
            <div style={{display:"flex",alignItems:"center",gap:7,marginBottom:4}}>
              <span style={{fontWeight:700,fontSize:14}}>{c.name}</span>
              <span className={`pill ${c.type==="presentiel"?"pb":"pg"}`} style={{fontSize:8}}>{c.type==="presentiel"?"🏋️ Présentiel":"💻 En ligne"}</span>
            </div>
            <div style={{fontSize:11,color:"#444",marginBottom:4}}>{c.goal} · {o.emoji} {o.nom}</div>
            {c.type==="presentiel"&&<><PBar value={st.pct}/><div style={{display:"flex",gap:10,marginTop:4}}><span style={{fontSize:10,color:"#B8D400"}}>✅{st.faites}</span>{st.dues>0&&<span style={{fontSize:10,color:"#ff4444"}}>🔴{st.dues}</span>}<span style={{fontSize:10,color:"#333"}}>/{c.pack}</span></div></>}
            {c.type==="enligne"&&<div style={{fontSize:10,color:o.color}}>{o.prix}€/mois · {c.paiements.filter(p=>p.statut==="payé").length} mois payés</div>}
          </div>
          <div style={{color:"#222",fontSize:16}}>›</div>
        </div>;
      })}
    </div>
    <button className="btn" onClick={()=>setShowNew(true)}>+ Nouveau client</button>
    {showNew&&<div className="mo" onClick={()=>setShowNew(false)}><div className="ms" onClick={e=>e.stopPropagation()}>
      <div className="mh"/>
      <div style={{fontFamily:"'Bebas Neue'",fontSize:22,letterSpacing:1,marginBottom:18}}>NOUVEAU CLIENT</div>
      <div style={{display:"flex",flexDirection:"column",gap:12}}>
        <div><label style={{fontSize:10,color:"#444",textTransform:"uppercase",letterSpacing:.5,display:"block",marginBottom:5}}>Nom complet *</label><input placeholder="Ex: Marie Dupont" value={nc.name} onChange={e=>setNc(p=>({...p,name:e.target.value}))}/></div>
        <div><label style={{fontSize:10,color:"#444",textTransform:"uppercase",letterSpacing:.5,display:"block",marginBottom:5}}>Objectif</label><input placeholder="Ex: Perte de poids" value={nc.goal} onChange={e=>setNc(p=>({...p,goal:e.target.value}))}/></div>
        <div><label style={{fontSize:10,color:"#444",textTransform:"uppercase",letterSpacing:.5,display:"block",marginBottom:5}}>Type</label>
          <div className="tg"><button className={`tb ${nc.type==="presentiel"?"on":"off"}`} onClick={()=>setNc(p=>({...p,type:"presentiel",offre:"p_sport"}))}>🏋️ Présentiel</button><button className={`tb ${nc.type==="enligne"?"on":"off"}`} onClick={()=>setNc(p=>({...p,type:"enligne",offre:"l_sport"}))}>💻 En ligne</button></div>
        </div>
        {nc.type==="presentiel"&&<div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
          <div><label style={{fontSize:10,color:"#444",textTransform:"uppercase",letterSpacing:.5,display:"block",marginBottom:5}}>Tarif séance (€)</label><input type="number" placeholder="50" value={nc.tarif} onChange={e=>setNc(p=>({...p,tarif:e.target.value}))}/></div>
          <div><label style={{fontSize:10,color:"#444",textTransform:"uppercase",letterSpacing:.5,display:"block",marginBottom:5}}>Pack (séances)</label><input type="number" placeholder="10" value={nc.pack} onChange={e=>setNc(p=>({...p,pack:e.target.value}))}/></div>
        </div>}
        <div><label style={{fontSize:10,color:"#444",textTransform:"uppercase",letterSpacing:.5,display:"block",marginBottom:5}}>Formule app</label>
          {(nc.type==="presentiel"?OFFRES_P:OFFRES_L).map(o=>(
            <div key={o.id} onClick={()=>setNc(p=>({...p,offre:o.id}))} style={{display:"flex",alignItems:"center",gap:11,padding:"10px 12px",borderRadius:12,cursor:"pointer",marginBottom:7,background:nc.offre===o.id?o.bg:"#0d0d0d",border:`1px solid ${nc.offre===o.id?o.color:"#1e1e1e"}`,transition:"all .2s"}}>
              <span style={{fontSize:18}}>{o.emoji}</span>
              <div style={{flex:1}}><div style={{fontWeight:700,fontSize:13,color:nc.offre===o.id?o.color:"#fff"}}>{o.nom}</div></div>
              <div style={{fontFamily:"'Bebas Neue'",fontSize:18,color:o.color}}>{o.prix}€</div>
            </div>
          ))}
        </div>
        <div style={{display:"flex",gap:10,marginTop:4}}><button className="btn-o" style={{flex:1}} onClick={()=>setShowNew(false)}>Annuler</button><button className="btn" style={{flex:2}} onClick={addClient}>Créer le client</button></div>
      </div>
    </div></div>}
  </div>;

  const c=clients.find(x=>x.id===sel); const st=clientStats(c); const o=getOffre(c.offre);
  return <div style={{padding:"0 16px 16px",display:"flex",flexDirection:"column",gap:13}} className="fu">
    <button className="btn-o" style={{alignSelf:"flex-start",padding:"8px 14px",fontSize:12}} onClick={()=>setSel(null)}>← Retour</button>
    <div className="card" style={{background:"linear-gradient(140deg,#111,#141a00)"}}>
      <div style={{display:"flex",alignItems:"center",gap:14,marginBottom:14}}>
        <Av initials={c.avatar} size={52}/>
        <div style={{flex:1}}>
          <div style={{fontFamily:"'Bebas Neue'",fontSize:22,letterSpacing:.8}}>{c.name}</div>
          <div style={{fontSize:12,color:"#444",marginTop:3}}>{c.goal}</div>
          <div style={{display:"flex",gap:6,marginTop:6}}>
            <span className={`pill ${c.type==="presentiel"?"pb":"pg"}`}>{c.type==="presentiel"?"🏋️ Présentiel":"💻 En ligne"}</span>
            <span className="pill pg">{o.emoji} {o.nom} · {o.prix}€/mois</span>
          </div>
        </div>
      </div>
      {c.type==="presentiel"&&<>
        <div style={{display:"flex",justifyContent:"space-between",marginBottom:5}}><span style={{fontSize:11,color:"#444"}}>Pack {c.pack} séances</span><span style={{fontSize:11,color:"#B8D400",fontWeight:700}}>{st.pct}%</span></div>
        <PBar value={st.pct} h={7}/>
        <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:8,marginTop:12}}>
          {[{l:"Faites",v:st.faites,c:"#B8D400"},{l:"Rattrapées",v:st.rattrapees,c:"#ffa032"},{l:"Dues",v:st.dues,c:"#ff4444"},{l:"Restantes",v:st.restantes,c:"#aaa"}].map((s,i)=>(
            <div key={i} style={{background:"#0d0d0d",borderRadius:11,padding:"9px 6px",textAlign:"center",border:"1px solid #1a1a1a"}}>
              <div style={{fontFamily:"'Bebas Neue'",fontSize:18,color:s.c}}>{s.v}</div>
              <div style={{fontSize:9,color:"#333",textTransform:"uppercase",letterSpacing:.3}}>{s.l}</div>
            </div>
          ))}
        </div>
      </>}
      {c.type==="enligne"&&<div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
        {[{l:"Mois payés",v:c.paiements.filter(p=>p.statut==="payé").length,c:"#B8D400"},{l:"Total encaissé",v:`${c.paiements.filter(p=>p.statut==="payé").reduce((s,p)=>s+p.montant,0)}€`,c:"#B8D400"}].map((s,i)=>(
          <div key={i} style={{background:"#0d0d0d",borderRadius:11,padding:"10px 8px",textAlign:"center",border:"1px solid #1a1a1a"}}>
            <div style={{fontFamily:"'Bebas Neue'",fontSize:22,color:s.c}}>{s.v}</div>
            <div style={{fontSize:9,color:"#333",textTransform:"uppercase",letterSpacing:.3}}>{s.l}</div>
          </div>
        ))}
      </div>}
    </div>
  </div>;
}

// ─── SÉANCES SCREEN ───────────────────────────────────────────────────────────
function SeancesScreen({clients,setClients}){
  const [sel,setSel]=useState(null);
  const [showAdd,setShowAdd]=useState(false);
  const [newStatut,setNewStatut]=useState(null);
  const [newDate,setNewDate]=useState(today());
  const [newNote,setNewNote]=useState("");
  const [filtre,setFiltre]=useState("tous");

  const presClients=clients.filter(c=>c.type==="presentiel");
  const client=sel?clients.find(c=>c.id===sel):null;

  const addSeance=()=>{
    if(!newStatut) return;
    setClients(prev=>prev.map(c=>{
      if(c.id!==sel) return c;
      const id=Math.max(0,...c.seances.map(s=>s.id),0)+1;
      return{...c,seances:[...c.seances,{id,date:newDate,statut:newStatut,note:newNote}]};
    }));
    setShowAdd(false); setNewNote(""); setNewDate(today()); setNewStatut(null);
  };

  const toggleStatut=(cId,sId)=>setClients(prev=>prev.map(c=>{
    if(c.id!==cId) return c;
    return{...c,seances:c.seances.map(s=>{
      if(s.id!==sId) return s;
      const order=["faite","due","rattrapee","coach"];
      const next=order[(order.indexOf(s.statut)+1)%order.length];
      return{...s,statut:next};
    })};
  }));

  const deleteSeance=(cId,sId)=>setClients(prev=>prev.map(c=>c.id!==cId?c:{...c,seances:c.seances.filter(s=>s.id!==sId)}));

  // ── Vue liste clients présentiel ──
  if(!sel) return <div style={{padding:"0 16px 16px",display:"flex",flexDirection:"column",gap:13}} className="fu">
    <div className="card" style={{background:"linear-gradient(140deg,#111,#141a00)"}}>
      <div className="st">RÉCAP GLOBAL PRÉSENTIEL</div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:10}}>
        {[
          {l:"Séances faites",v:presClients.reduce((s,c)=>s+c.seances.filter(x=>x.statut==="faite").length,0),c:"#B8D400"},
          {l:"Dues 🔴",v:presClients.reduce((s,c)=>s+c.seances.filter(x=>x.statut==="due").length,0),c:"#ff4444"},
          {l:"Rattrapées 🔄",v:presClients.reduce((s,c)=>s+c.seances.filter(x=>x.statut==="rattrapee").length,0),c:"#ffa032"},
        ].map((s,i)=>(
          <div key={i} style={{background:"#0d0d0d",borderRadius:12,padding:"12px 8px",textAlign:"center",border:"1px solid #1a1a1a"}}>
            <div style={{fontFamily:"'Bebas Neue'",fontSize:24,color:s.c}}>{s.v}</div>
            <div style={{fontSize:9,color:"#333",textTransform:"uppercase",letterSpacing:.3}}>{s.l}</div>
          </div>
        ))}
      </div>
    </div>

    <div className="card">
      <div className="st">CLIENTS PRÉSENTIEL</div>
      {presClients.map(c=>{
        const st=clientStats(c);
        return <div key={c.id} className="cr" onClick={()=>setSel(c.id)}>
          <Av initials={c.avatar} size={44}/>
          <div style={{flex:1,minWidth:0}}>
            <div style={{display:"flex",alignItems:"center",gap:7,marginBottom:5}}>
              <span style={{fontWeight:700,fontSize:14}}>{c.name}</span>
              {st.dues>0&&<span className="pill pr" style={{fontSize:8}}>🔴 {st.dues} due{st.dues>1?"s":""}</span>}
              {st.restantes<=2&&st.restantes>0&&<span className="pill po" style={{fontSize:8}}>⚠️{st.restantes}restantes</span>}
            </div>
            <PBar value={st.pct}/>
            <div style={{display:"flex",gap:10,marginTop:4}}>
              <span style={{fontSize:10,color:"#B8D400"}}>✅{st.faites}</span>
              {st.rattrapees>0&&<span style={{fontSize:10,color:"#ffa032"}}>🔄{st.rattrapees}</span>}
              {st.dues>0&&<span style={{fontSize:10,color:"#ff4444"}}>🔴{st.dues}</span>}
              <span style={{fontSize:10,color:"#333"}}>/{c.pack} séances</span>
            </div>
          </div>
          <div style={{textAlign:"right",flexShrink:0}}>
            <div style={{fontFamily:"'Bebas Neue'",fontSize:22,color:"#B8D400"}}>{st.faites+st.rattrapees}<span style={{fontSize:11,color:"#333"}}>/{c.pack}</span></div>
            {st.aRecouvrer>0&&<div style={{fontSize:10,color:"#ff4444",marginTop:2}}>{st.aRecouvrer}€ dû</div>}
          </div>
          <div style={{color:"#222",fontSize:16}}>›</div>
        </div>;
      })}
    </div>
  </div>;

  // ── Vue détail client ──
  const st=clientStats(client);
  const seancesFiltrees=filtre==="tous"?client.seances:client.seances.filter(s=>s.statut===filtre);

  return <div style={{padding:"0 16px 16px",display:"flex",flexDirection:"column",gap:13}} className="fu">
    <button className="btn-o" style={{alignSelf:"flex-start",padding:"8px 14px",fontSize:12}} onClick={()=>setSel(null)}>← Retour</button>

    {/* Header client */}
    <div className="card" style={{background:"linear-gradient(140deg,#111,#141a00)"}}>
      <div style={{display:"flex",alignItems:"center",gap:14,marginBottom:14}}>
        <Av initials={client.avatar} size={50}/>
        <div style={{flex:1}}>
          <div style={{fontFamily:"'Bebas Neue'",fontSize:20,letterSpacing:.8}}>{client.name}</div>
          <div style={{fontSize:12,color:"#444",marginTop:2}}>{client.goal} · {client.tarif}€/séance</div>
        </div>
        <div style={{textAlign:"center",background:"rgba(184,212,0,.07)",border:"1px solid rgba(184,212,0,.14)",borderRadius:13,padding:"8px 12px"}}>
          <div style={{fontFamily:"'Bebas Neue'",fontSize:28,color:"#B8D400",lineHeight:1}}>{st.faites+st.rattrapees}</div>
          <div style={{fontSize:10,color:"#444"}}>/{client.pack}</div>
        </div>
      </div>
      <PBar value={st.pct} h={7}/>
      <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:7,marginTop:12}}>
        {[{l:"Faites",v:st.faites,c:"#B8D400"},{l:"Rattrapées",v:st.rattrapees,c:"#ffa032"},{l:"Dues 🔴",v:st.dues,c:"#ff4444"},{l:"Par moi",v:st.parCoach,c:"#888"}].map((s,i)=>(
          <div key={i} style={{background:"#0d0d0d",borderRadius:10,padding:"9px 6px",textAlign:"center",border:"1px solid #1a1a1a"}}>
            <div style={{fontFamily:"'Bebas Neue'",fontSize:18,color:s.c}}>{s.v}</div>
            <div style={{fontSize:9,color:"#2e2e2e",textTransform:"uppercase",letterSpacing:.3}}>{s.l}</div>
          </div>
        ))}
      </div>
      {st.dues>0&&<div style={{marginTop:10,background:"rgba(255,68,68,.06)",border:"1px solid rgba(255,68,68,.18)",borderRadius:11,padding:"9px 12px"}}>
        <span style={{fontSize:12,color:"#ff4444",fontWeight:700}}>⚠️ {st.dues} séance(s) due(s) — {st.aRecouvrer}€ à recouvrer</span>
      </div>}
    </div>

    {/* Grille visuelle */}
    <div className="card">
      <div className="st">GRILLE DU PACK ({client.pack} SÉANCES)</div>
      <div style={{display:"flex",flexWrap:"wrap",gap:6,marginBottom:10}}>
        {Array.from({length:client.pack}).map((_,i)=>{
          const s=client.seances[i]; const st_s=s?STATUTS[s.statut]:null;
          return <div key={i} className="sdot" style={{background:st_s?st_s.bg:"#131313",border:`1px solid ${st_s?st_s.border:"#1c1c1c"}`,color:st_s?st_s.color:"#2a2a2a",fontSize:s?16:12,boxShadow:s?.statut==="faite"?"0 0 8px rgba(184,212,0,.15)":"none"}}>
            {s?st_s.emoji:i+1}
          </div>;
        })}
      </div>
      <div style={{display:"flex",flexWrap:"wrap",gap:10}}>
        {Object.entries(STATUTS).map(([k,s])=>(
          <div key={k} style={{display:"flex",alignItems:"center",gap:5}}><span style={{fontSize:12}}>{s.emoji}</span><span style={{fontSize:9,color:"#3a3a3a"}}>{s.label}</span></div>
        ))}
      </div>
    </div>

    {/* Boutons */}
    <div style={{display:"flex",gap:10}}>
      <button onClick={()=>{setNewStatut("faite");setShowAdd(true);}} style={{flex:1,background:"rgba(184,212,0,.12)",color:"#B8D400",border:"1px solid rgba(184,212,0,.25)",borderRadius:12,padding:"13px 8px",fontFamily:"'DM Sans'",fontWeight:700,fontSize:12,cursor:"pointer",transition:"all .2s"}}>✅ Valider</button>
      <button onClick={()=>{setNewStatut("due");setShowAdd(true);}} style={{flex:1,background:"rgba(255,68,68,.08)",color:"#ff4444",border:"1px solid rgba(255,68,68,.2)",borderRadius:12,padding:"13px 8px",fontFamily:"'DM Sans'",fontWeight:700,fontSize:12,cursor:"pointer",transition:"all .2s"}}>🔴 Due</button>
      <button onClick={()=>{setNewStatut("rattrapee");setShowAdd(true);}} style={{flex:1,background:"rgba(255,160,50,.08)",color:"#ffa032",border:"1px solid rgba(255,160,50,.2)",borderRadius:12,padding:"13px 8px",fontFamily:"'DM Sans'",fontWeight:700,fontSize:12,cursor:"pointer",transition:"all .2s"}}>🔄 Rattrapée</button>
      <button onClick={()=>{setNewStatut("coach");setShowAdd(true);}} style={{flex:1,background:"rgba(180,180,180,.07)",color:"#888",border:"1px solid rgba(180,180,180,.18)",borderRadius:12,padding:"13px 8px",fontFamily:"'DM Sans'",fontWeight:700,fontSize:12,cursor:"pointer",transition:"all .2s"}}>🟡 Moi</button>
    </div>

    {/* Historique */}
    <div className="card">
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12}}>
        <div className="st" style={{marginBottom:0}}>HISTORIQUE</div>
        <div style={{display:"flex",gap:5,flexWrap:"wrap"}}>
          {["tous","faite","due","rattrapee","coach"].map(f=>(
            <button key={f} onClick={()=>setFiltre(f)} style={{padding:"4px 9px",borderRadius:8,border:`1px solid ${filtre===f?"#B8D400":"#1e1e1e"}`,background:filtre===f?"rgba(184,212,0,.1)":"transparent",color:filtre===f?"#B8D400":"#444",fontSize:9,fontWeight:700,cursor:"pointer",textTransform:"uppercase"}}>
              {f==="tous"?"Tous":STATUTS[f]?.emoji+" "+f}
            </button>
          ))}
        </div>
      </div>
      {[...seancesFiltrees].reverse().map((s,i)=>{
        const st_s=STATUTS[s.statut];
        return <div key={s.id} style={{display:"flex",alignItems:"flex-start",gap:11,padding:"11px 0",borderBottom:i<seancesFiltrees.length-1?"1px solid #161616":"none"}}>
          <div style={{width:34,height:34,borderRadius:10,flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center",fontSize:16,background:st_s.bg,border:`1px solid ${st_s.border}`}}>{st_s.emoji}</div>
          <div style={{flex:1}}>
            <div style={{display:"flex",alignItems:"center",gap:7,marginBottom:2}}>
              <span style={{fontWeight:700,fontSize:13}}>Séance #{s.id}</span>
              <span style={{fontSize:9,color:st_s.color,background:st_s.bg,padding:"2px 8px",borderRadius:6,fontWeight:700,cursor:"pointer"}} onClick={()=>toggleStatut(client.id,s.id)}>{st_s.label}</span>
            </div>
            <div style={{fontSize:11,color:"#3a3a3a"}}>📅 {s.date}</div>
            {s.note&&<div style={{fontSize:12,color:"#555",marginTop:3,fontStyle:"italic"}}>💬 {s.note}</div>}
          </div>
          <button onClick={()=>deleteSeance(client.id,s.id)} style={{width:26,height:26,borderRadius:7,background:"transparent",border:"1px solid #1e1e1e",color:"#2e2e2e",cursor:"pointer",fontSize:12,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,transition:"all .2s"}}
            onMouseEnter={e=>{e.currentTarget.style.borderColor="#ff4444";e.currentTarget.style.color="#ff4444";}}
            onMouseLeave={e=>{e.currentTarget.style.borderColor="#1e1e1e";e.currentTarget.style.color="#2e2e2e";}}>✕</button>
        </div>;
      })}
    </div>

    {/* Modal ajout */}
    {showAdd&&<div className="mo" onClick={()=>setShowAdd(false)}><div className="ms" onClick={e=>e.stopPropagation()}>
      <div className="mh"/>
      <div style={{display:"flex",alignItems:"center",gap:12,marginBottom:18}}>
        <span style={{fontSize:28}}>{newStatut?STATUTS[newStatut].emoji:"📋"}</span>
        <div>
          <div style={{fontFamily:"'Bebas Neue'",fontSize:20,letterSpacing:1}}>{newStatut?STATUTS[newStatut].label:"ENREGISTRER"}</div>
          <div style={{fontSize:12,color:"#444"}}>{client.name} · Séance #{client.seances.length+1}</div>
        </div>
      </div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:14}}>
        {Object.entries(STATUTS).map(([k,s])=>(
          <button key={k} onClick={()=>setNewStatut(k)} style={{padding:"12px 8px",borderRadius:12,cursor:"pointer",background:newStatut===k?s.bg:"#0d0d0d",border:`2px solid ${newStatut===k?s.color:"#1e1e1e"}`,color:newStatut===k?s.color:"#555",fontFamily:"'DM Sans'",fontWeight:700,fontSize:11,transition:"all .2s",display:"flex",flexDirection:"column",alignItems:"center",gap:5}}>
            <span style={{fontSize:20}}>{s.emoji}</span>{s.label}
          </button>
        ))}
      </div>
      <div style={{marginBottom:12}}><label style={{fontSize:10,color:"#444",textTransform:"uppercase",letterSpacing:.5,display:"block",marginBottom:5}}>Date</label><input value={newDate} onChange={e=>setNewDate(e.target.value)} placeholder="JJ/MM/AA"/></div>
      <div style={{marginBottom:16}}><label style={{fontSize:10,color:"#444",textTransform:"uppercase",letterSpacing:.5,display:"block",marginBottom:5}}>Note</label><textarea rows={2} value={newNote} onChange={e=>setNewNote(e.target.value)} placeholder="Observation, raison..."/></div>
      <div style={{display:"flex",gap:10}}><button className="btn-o" style={{flex:1}} onClick={()=>setShowAdd(false)}>Annuler</button><button className="btn" style={{flex:2}} onClick={addSeance} disabled={!newStatut}>Confirmer</button></div>
    </div></div>}
  </div>;
}

// ─── PAIEMENTS SCREEN ─────────────────────────────────────────────────────────
function PaiementsScreen({clients,setClients}){
  const [sel,setSel]=useState(null);
  const [showAdd,setShowAdd]=useState(false);
  const [modeF,setModeF]=useState("tous");
  const [nm,setNm]=useState(""); const [nmt,setNmt]=useState(""); const [nme,setNme]=useState("CB"); const [nst,setNst]=useState("payé");

  const client=sel?clients.find(c=>c.id===sel):null;

  const totalPaye=clients.reduce((s,c)=>s+c.paiements.filter(p=>p.statut==="payé").reduce((a,p)=>a+p.montant,0),0);
  const totalAtt=clients.reduce((s,c)=>s+c.paiements.filter(p=>p.statut==="en attente").reduce((a,p)=>a+p.montant,0),0);
  const totalImp=clients.reduce((s,c)=>s+c.paiements.filter(p=>p.statut==="impayé").reduce((a,p)=>a+p.montant,0),0);
  const totalMRR=clients.reduce((s,c)=>s+getOffre(c.offre).prix,0);

  const togglePay=(cId,pId)=>setClients(prev=>prev.map(c=>{
    if(c.id!==cId) return c;
    return{...c,paiements:c.paiements.map(p=>{if(p.id!==pId) return p; const n=p.statut==="payé"?"en attente":p.statut==="en attente"?"impayé":"payé"; return{...p,statut:n};})};
  }));

  const addPay=()=>{
    const o=getOffre(client.offre);
    setClients(prev=>prev.map(c=>{
      if(c.id!==sel) return c;
      const id=Math.max(0,...c.paiements.map(p=>p.id),0)+1;
      return{...c,paiements:[...c.paiements,{id,mois:nm||"Mois",montant:Number(nmt)||o.prix,statut:nst,date:today(),methode:nme}]};
    }));
    setShowAdd(false); setNm(""); setNmt(""); setNst("payé");
  };

  const clientsFiltres=clients.filter(c=>modeF==="tous"||c.type===modeF);

  if(!sel) return <div style={{padding:"0 16px 16px",display:"flex",flexDirection:"column",gap:13}} className="fu">
    <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
      <div className="card" style={{background:"linear-gradient(140deg,#111,#141a00)",padding:15}}>
        <div style={{fontSize:10,color:"#3a3a3a",textTransform:"uppercase",letterSpacing:.5,marginBottom:4}}>MRR</div>
        <div style={{fontFamily:"'Bebas Neue'",fontSize:30,color:"#B8D400",lineHeight:1}}>{totalMRR}€</div>
        <div style={{fontSize:10,color:"#444",marginTop:3}}>{clients.length} abonnés</div>
      </div>
      <div style={{display:"flex",flexDirection:"column",gap:7}}>
        {[{l:"✅ Encaissé",v:`${totalPaye}€`,c:"#B8D400"},{l:"⏳ Attente",v:`${totalAtt}€`,c:"#ffa032"},{l:"❌ Impayé",v:`${totalImp}€`,c:"#ff4444"}].map((s,i)=>(
          <div key={i} className="card" style={{padding:"9px 12px",display:"flex",justifyContent:"space-between",alignItems:"center",border:s.l.includes("❌")&&totalImp>0?"1px solid rgba(255,68,68,.2)":undefined}}>
            <span style={{fontSize:11,color:"#444"}}>{s.l}</span>
            <span style={{fontFamily:"'Bebas Neue'",fontSize:17,color:s.c}}>{s.v}</span>
          </div>
        ))}
      </div>
    </div>

    <div style={{display:"flex",gap:7}}>
      {[{k:"tous",l:"Tous"},{k:"presentiel",l:"🏋️ Présentiel"},{k:"enligne",l:"💻 En ligne"}].map(f=>(
        <button key={f.k} onClick={()=>setModeF(f.k)} style={{padding:"6px 12px",borderRadius:9,border:`1px solid ${modeF===f.k?"#B8D400":"#1e1e1e"}`,background:modeF===f.k?"rgba(184,212,0,.1)":"transparent",color:modeF===f.k?"#B8D400":"#444",fontSize:11,fontWeight:700,cursor:"pointer",transition:"all .2s"}}>{f.l}</button>
      ))}
    </div>

    <div className="card">
      <div className="st">ABONNEMENTS</div>
      {clientsFiltres.map(c=>{
        const o=getOffre(c.offre);
        const imp=c.paiements.filter(p=>p.statut==="impayé").length;
        const att=c.paiements.filter(p=>p.statut==="en attente").length;
        return <div key={c.id} className="cr" onClick={()=>setSel(c.id)}>
          <Av initials={c.avatar} size={44}/>
          <div style={{flex:1,minWidth:0}}>
            <div style={{display:"flex",alignItems:"center",gap:7,marginBottom:4}}>
              <span style={{fontWeight:700,fontSize:13}}>{c.name}</span>
              <span style={{fontSize:8,color:c.type==="presentiel"?"#50a0ff":"#B8D400",background:c.type==="presentiel"?"rgba(80,160,255,.08)":"rgba(184,212,0,.08)",padding:"2px 7px",borderRadius:6,fontWeight:700}}>{c.type==="presentiel"?"🏋️":"💻"}</span>
            </div>
            <div style={{fontSize:11,color:o.color,marginBottom:3}}>{o.emoji} {o.nom}</div>
            <div style={{display:"flex",gap:8}}>
              {imp>0&&<span style={{fontSize:10,color:"#ff4444"}}>❌ {imp} impayé</span>}
              {att>0&&<span style={{fontSize:10,color:"#ffa032"}}>⏳ {att} en attente</span>}
              {imp===0&&att===0&&<span style={{fontSize:10,color:"#B8D400"}}>✅ À jour</span>}
            </div>
          </div>
          <div style={{textAlign:"right",flexShrink:0}}>
            <div style={{fontFamily:"'Bebas Neue'",fontSize:20,color:o.color}}>{o.prix}€</div>
            <div style={{fontSize:10,color:"#333"}}>/mois</div>
          </div>
          <div style={{color:"#222",fontSize:16}}>›</div>
        </div>;
      })}
    </div>
  </div>;

  const o=getOffre(client.offre);
  return <div style={{padding:"0 16px 16px",display:"flex",flexDirection:"column",gap:13}} className="fu">
    <button className="btn-o" style={{alignSelf:"flex-start",padding:"8px 14px",fontSize:12}} onClick={()=>setSel(null)}>← Retour</button>
    <div className="card" style={{background:"linear-gradient(140deg,#111,#141a00)"}}>
      <div style={{display:"flex",alignItems:"center",gap:14,marginBottom:14}}>
        <Av initials={client.avatar} size={50}/>
        <div style={{flex:1}}>
          <div style={{fontFamily:"'Bebas Neue'",fontSize:20,letterSpacing:.8}}>{client.name}</div>
          <div style={{display:"flex",gap:6,marginTop:5}}>
            <span className={`pill ${client.type==="presentiel"?"pb":"pg"}`} style={{fontSize:8}}>{client.type==="presentiel"?"🏋️ Présentiel":"💻 En ligne"}</span>
            <span className="pill pg" style={{fontSize:8}}>{o.emoji} {o.nom}</span>
          </div>
        </div>
        <div style={{textAlign:"center",background:"rgba(184,212,0,.07)",border:"1px solid rgba(184,212,0,.14)",borderRadius:13,padding:"8px 12px"}}>
          <div style={{fontFamily:"'Bebas Neue'",fontSize:26,color:"#B8D400",lineHeight:1}}>{o.prix}€</div>
          <div style={{fontSize:10,color:"#444"}}>/mois</div>
        </div>
      </div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:8}}>
        {[{l:"Payés",v:client.paiements.filter(p=>p.statut==="payé").length,c:"#B8D400"},{l:"Encaissé",v:`${client.paiements.filter(p=>p.statut==="payé").reduce((s,p)=>s+p.montant,0)}€`,c:"#B8D400"},{l:"Depuis",v:client.paiements[0]?.date||"—",c:"#555"}].map((s,i)=>(
          <div key={i} style={{background:"#0d0d0d",borderRadius:10,padding:"9px 7px",textAlign:"center",border:"1px solid #1a1a1a"}}>
            <div style={{fontFamily:"'Bebas Neue'",fontSize:16,color:s.c,lineHeight:1}}>{s.v}</div>
            <div style={{fontSize:9,color:"#2e2e2e",textTransform:"uppercase",letterSpacing:.3}}>{s.l}</div>
          </div>
        ))}
      </div>
    </div>

    <div className="card">
      <div className="st">HISTORIQUE PAIEMENTS</div>
      <div style={{fontSize:11,color:"#444",marginBottom:12}}>💡 Appuie sur un statut pour le changer</div>
      {client.paiements.length===0&&<div style={{color:"#2e2e2e",fontSize:13,textAlign:"center",padding:"16px 0"}}>Aucun paiement</div>}
      {[...client.paiements].reverse().map((p,i)=>(
        <div key={p.id} style={{display:"flex",alignItems:"center",gap:11,padding:"11px 0",borderBottom:i<client.paiements.length-1?"1px solid #161616":"none"}}>
          <div style={{flex:1}}>
            <div style={{fontWeight:700,fontSize:13,marginBottom:2}}>{p.mois}</div>
            <div style={{fontSize:11,color:"#3a3a3a"}}>📅 {p.date} · {p.methode}</div>
          </div>
          <div style={{fontFamily:"'Bebas Neue'",fontSize:20,marginRight:10}}>{p.montant}€</div>
          <StatutPay statut={p.statut} onClick={()=>togglePay(client.id,p.id)}/>
        </div>
      ))}
    </div>

    <button className="btn" onClick={()=>setShowAdd(true)}>+ Ajouter un paiement</button>

    {showAdd&&<div className="mo" onClick={()=>setShowAdd(false)}><div className="ms" onClick={e=>e.stopPropagation()}>
      <div className="mh"/>
      <div style={{fontFamily:"'Bebas Neue'",fontSize:22,letterSpacing:1,marginBottom:4}}>NOUVEAU PAIEMENT</div>
      <div style={{fontSize:12,color:"#444",marginBottom:18}}>{client.name} · {o.prix}€/mois</div>
      <div style={{display:"flex",flexDirection:"column",gap:12}}>
        <div><label style={{fontSize:10,color:"#444",textTransform:"uppercase",letterSpacing:.5,display:"block",marginBottom:5}}>Mois</label><input placeholder="Ex: Mai 2026" value={nm} onChange={e=>setNm(e.target.value)}/></div>
        <div><label style={{fontSize:10,color:"#444",textTransform:"uppercase",letterSpacing:.5,display:"block",marginBottom:5}}>Montant (€)</label><input type="number" placeholder={`${o.prix} par défaut`} value={nmt} onChange={e=>setNmt(e.target.value)}/></div>
        <div><label style={{fontSize:10,color:"#444",textTransform:"uppercase",letterSpacing:.5,display:"block",marginBottom:5}}>Moyen de paiement</label>
          <div style={{display:"flex",gap:7,flexWrap:"wrap"}}>
            {["CB","Virement","Espèces","PayPal","Lydia"].map(m=>(
              <button key={m} onClick={()=>setNme(m)} style={{padding:"7px 12px",borderRadius:9,border:`1px solid ${nme===m?"#B8D400":"#1e1e1e"}`,background:nme===m?"rgba(184,212,0,.1)":"transparent",color:nme===m?"#B8D400":"#555",fontSize:12,fontWeight:700,cursor:"pointer",transition:"all .2s"}}>{m}</button>
            ))}
          </div>
        </div>
        <div><label style={{fontSize:10,color:"#444",textTransform:"uppercase",letterSpacing:.5,display:"block",marginBottom:5}}>Statut</label>
          <div style={{display:"flex",gap:8}}>
            {["payé","en attente","impayé"].map(s=>(
              <button key={s} onClick={()=>setNst(s)} style={{flex:1,padding:"9px 6px",borderRadius:10,border:`1px solid ${nst===s?"#B8D400":"#1e1e1e"}`,background:nst===s?"rgba(184,212,0,.1)":"transparent",color:nst===s?"#B8D400":"#555",fontSize:10,fontWeight:700,cursor:"pointer",transition:"all .2s",textAlign:"center"}}>
                {s==="payé"?"✅ Payé":s==="en attente"?"⏳ Attente":"❌ Impayé"}
              </button>
            ))}
          </div>
        </div>
        <div style={{display:"flex",gap:10,marginTop:6}}><button className="btn-o" style={{flex:1}} onClick={()=>setShowAdd(false)}>Annuler</button><button className="btn" style={{flex:2}} onClick={addPay}>Enregistrer</button></div>
      </div>
    </div></div>}
  </div>;
}

// ─── OFFRES SCREEN ────────────────────────────────────────────────────────────
function OffresScreen(){
  const [mode,setMode]=useState("presentiel");
  const [sel,setSel]=useState(null);
  const offres=mode==="presentiel"?OFFRES_P:OFFRES_L;
  const [counts,setCounts]=useState({p_base:3,p_sport:5,p_premium:4,l_notif:3,l_sport:6,l_premium:4});

  const total=offres.reduce((s,o)=>s+(counts[o.id]*o.prix),0);

  return <div style={{padding:"0 16px 16px",display:"flex",flexDirection:"column",gap:14}} className="fu">
    <div className="tg">
      <button className={`tb ${mode==="presentiel"?"on":"off"}`} onClick={()=>{setMode("presentiel");setSel(null);}}>🏋️ Présentiel</button>
      <button className={`tb ${mode==="enligne"?"on":"off"}`} onClick={()=>{setMode("enligne");setSel(null);}}>💻 En ligne</button>
    </div>

    <div style={{background:mode==="presentiel"?"rgba(80,160,255,.07)":"rgba(184,212,0,.07)",border:`1px solid ${mode==="presentiel"?"rgba(80,160,255,.18)":"rgba(184,212,0,.18)"}`,borderRadius:14,padding:"12px 14px"}}>
      <div style={{fontWeight:700,fontSize:13,color:mode==="presentiel"?"#50a0ff":"#B8D400",marginBottom:4}}>{mode==="presentiel"?"🏋️ Clients Fitness Park Ermont":"💻 Clients coaching à distance"}</div>
      <div style={{fontSize:12,color:"#555",lineHeight:1.5}}>{mode==="presentiel"?"Ils paient déjà 50€/séance. L'app est un service additionnel entre 10 et 30€/mois.":"Tu es leur seul coach. Prix compétitifs vs le marché (150-200€/mois ailleurs)."}</div>
    </div>

    {offres.map(o=>(
      <div key={o.id} className={`oc ${sel===o.id?"sel":""}`} onClick={()=>setSel(sel===o.id?null:o.id)}
        style={{background:sel===o.id?o.bg:"#111",border:`2px solid ${sel===o.id?o.color:"#1d1d1d"}`,boxShadow:sel===o.id?`0 0 20px ${o.color}33`:"none"}}>
        {o.populaire&&<div className="bpop">⭐ Le plus choisi</div>}
        <div style={{display:"flex",alignItems:"center",gap:13,marginBottom:14}}>
          <div style={{width:46,height:46,borderRadius:13,background:o.bg,border:`1px solid ${o.border}`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:22,flexShrink:0}}>{o.emoji}</div>
          <div style={{flex:1}}>
            <div style={{fontFamily:"'Bebas Neue'",fontSize:20,color:sel===o.id?o.color:"#fff",letterSpacing:.8}}>{o.nom}</div>
            <div style={{fontSize:11,color:"#444",marginTop:1}}>{mode==="presentiel"?"Complément séances présentiel":"Coaching 100% à distance"}</div>
          </div>
          <div style={{textAlign:"right",flexShrink:0}}>
            <div style={{fontFamily:"'Bebas Neue'",fontSize:32,color:o.color,lineHeight:1}}>{o.prix}€</div>
            <div style={{fontSize:10,color:"#333"}}>/mois</div>
          </div>
        </div>
        {o.features.map((f,i)=>(
          <div key={i} className="fi">
            <div className="fic ok">✓</div>
            <span style={{fontSize:12,color:"#bbb"}}>{f}</span>
          </div>
        ))}
      </div>
    ))}

    {/* Simulateur */}
    <div className="card" style={{background:"linear-gradient(140deg,#111,#141a00)"}}>
      <div className="st">🧮 SIMULATEUR CA MENSUEL</div>
      {offres.map(o=>(
        <div key={o.id} style={{marginBottom:14}}>
          <div style={{display:"flex",justifyContent:"space-between",marginBottom:8}}>
            <span style={{fontSize:12,color:"#aaa"}}>{o.emoji} {o.nom} — {o.prix}€</span>
            <span style={{fontFamily:"'Bebas Neue'",fontSize:18,color:o.color}}>{counts[o.id]*o.prix}€</span>
          </div>
          <div style={{display:"flex",alignItems:"center",gap:12}}>
            <button className="ctrb" onClick={()=>setCounts(p=>({...p,[o.id]:Math.max(0,p[o.id]-1)}))}>−</button>
            <div style={{flex:1,textAlign:"center"}}>
              <div style={{fontFamily:"'Bebas Neue'",fontSize:26,color:o.color,lineHeight:1}}>{counts[o.id]}</div>
              <div style={{fontSize:10,color:"#333"}}>clients</div>
            </div>
            <button className="ctrb" onClick={()=>setCounts(p=>({...p,[o.id]:p[o.id]+1}))}>+</button>
          </div>
        </div>
      ))}
      <div style={{borderTop:"1px solid #1e1e1e",paddingTop:14}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:8}}>
          <span style={{fontSize:13,fontWeight:600}}>Total mensuel</span>
          <span style={{fontFamily:"'Bebas Neue'",fontSize:28,color:"#B8D400"}}>{total}€</span>
        </div>
        <div style={{background:"rgba(184,212,0,.06)",border:"1px solid rgba(184,212,0,.14)",borderRadius:12,padding:"10px 14px",textAlign:"center"}}>
          <span style={{fontSize:12,color:"#B8D400",fontWeight:600}}>💰 {total*12}€ / an estimé</span>
        </div>
      </div>
    </div>
  </div>;
}

// ─── MESSAGES SCREEN ──────────────────────────────────────────────────────────
function MessagesScreen({msgs}){
  const [active,setActive]=useState(null);
  const [text,setText]=useState("");
  if(active) return <div style={{padding:"0 16px 16px",display:"flex",flexDirection:"column",height:"calc(100vh-160px)"}} className="fu">
    <button className="btn-o" style={{alignSelf:"flex-start",padding:"8px 14px",fontSize:12,marginBottom:13}} onClick={()=>setActive(null)}>← Retour</button>
    <div className="card" style={{display:"flex",alignItems:"center",gap:12,marginBottom:13}}>
      <Av initials={active.av} size={44}/>
      <div style={{flex:1}}><div style={{fontWeight:700,fontSize:14}}>{active.from}</div><div style={{fontSize:11,color:"#B8D400",marginTop:1}}>● En ligne</div></div>
    </div>
    <div style={{flex:1,display:"flex",flexDirection:"column",gap:10,overflowY:"auto",paddingBottom:10}}>
      <div style={{alignSelf:"flex-start",background:"#161616",border:"1px solid #1e1e1e",borderRadius:"4px 16px 16px 16px",padding:"10px 14px",maxWidth:"80%",fontSize:13,color:"#bbb"}}>{active.text}</div>
      <div style={{alignSelf:"flex-end",background:"linear-gradient(135deg,#B8D400,#cde800)",borderRadius:"16px 4px 16px 16px",padding:"10px 14px",maxWidth:"80%",fontSize:13,color:"#0A0A0A",fontWeight:600,boxShadow:"0 3px 14px rgba(184,212,0,.22)"}}>Super, continue comme ça ! 💪</div>
    </div>
    <div style={{display:"flex",gap:10,paddingTop:10,borderTop:"1px solid #161616"}}>
      <input placeholder="Écrire un message..." value={text} onChange={e=>setText(e.target.value)} style={{flex:1}}/>
      <button className="btn" style={{width:"auto",padding:"12px 18px",fontSize:16}}>→</button>
    </div>
  </div>;

  return <div style={{padding:"0 16px 16px",display:"flex",flexDirection:"column",gap:11}} className="fu">
    {msgs.map(m=>(
      <div key={m.id} className="card tap" onClick={()=>setActive(m)}>
        <div style={{display:"flex",alignItems:"center",gap:12}}>
          <div style={{position:"relative"}}><Av initials={m.av} size={44}/>{!m.lu&&<div style={{position:"absolute",top:-2,right:-2,width:10,height:10,borderRadius:"50%",background:"#B8D400",border:"2px solid #0A0A0A"}}/>}</div>
          <div style={{flex:1,minWidth:0}}>
            <div style={{display:"flex",justifyContent:"space-between",marginBottom:3}}><span style={{fontWeight:700,fontSize:13}}>{m.from}</span><span style={{fontSize:10,color:"#333"}}>{m.time}</span></div>
            <div style={{fontSize:12,color:m.lu?"#333":"#777",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{m.text}</div>
          </div>
        </div>
      </div>
    ))}
  </div>;
}

// ─── APP SHELL ────────────────────────────────────────────────────────────────
const NAV=[
  {id:"dashboard", icon:"⊞",  label:"Accueil"},
  {id:"clients",   icon:"👥", label:"Clients"},
  {id:"seances",   icon:"📋", label:"Séances"},
  {id:"paiements", icon:"💰", label:"Paiements"},
  {id:"offres",    icon:"📦", label:"Offres"},
  {id:"messages",  icon:"💬", label:"Messages"},
];

export default function App(){
  const [screen,setScreen]=useState("dashboard");
  const [clients,setClients]=useState(initClients);
  const unread=MSGS.filter(m=>!m.lu).length;

  const screens={
    dashboard:<Dashboard clients={clients} msgs={MSGS} setScreen={setScreen}/>,
    clients:<ClientsScreen clients={clients} setClients={setClients}/>,
    seances:<SeancesScreen clients={clients} setClients={setClients}/>,
    paiements:<PaiementsScreen clients={clients} setClients={setClients}/>,
    offres:<OffresScreen/>,
    messages:<MessagesScreen msgs={MSGS}/>,
  };

  return <div style={{maxWidth:420,margin:"0 auto",minHeight:"100vh",background:"#080808",display:"flex",flexDirection:"column"}}>
    {/* HEADER */}
    <div style={{padding:"12px 18px 10px",borderBottom:"1px solid #141414",display:"flex",justifyContent:"space-between",alignItems:"center",position:"sticky",top:0,background:"rgba(8,8,8,.96)",backdropFilter:"blur(22px)",zIndex:10}}>
      <img src={LOGO} alt="Anastase Coaching" style={{height:34,objectFit:"contain"}}/>
      <div style={{display:"flex",alignItems:"center",gap:10}}>
        {unread>0&&<div style={{background:"rgba(255,68,68,.1)",border:"1px solid rgba(255,68,68,.2)",borderRadius:10,padding:"4px 10px"}}><span style={{fontSize:11,color:"#ff4444",fontWeight:700}}>💬 {unread} nouveau{unread>1?"x":""}</span></div>}
        <div style={{background:"rgba(184,212,0,.07)",border:"1px solid rgba(184,212,0,.14)",borderRadius:10,padding:"4px 10px"}}><span style={{fontFamily:"'Bebas Neue'",fontSize:13,color:"#B8D400",letterSpacing:1}}>COACH PRO</span></div>
      </div>
    </div>

    {/* TITLE */}
    <div style={{padding:"11px 18px 4px"}}>
      <h1 style={{fontFamily:"'Bebas Neue'",fontSize:17,letterSpacing:2}}>{NAV.find(n=>n.id===screen)?.label.toUpperCase()}</h1>
    </div>

    {/* CONTENT */}
    <div style={{flex:1,overflowY:"auto",paddingBottom:82}}>{screens[screen]}</div>

    {/* NAV */}
    <div style={{position:"fixed",bottom:0,left:"50%",transform:"translateX(-50%)",width:"100%",maxWidth:420,background:"rgba(6,6,6,.97)",backdropFilter:"blur(24px)",borderTop:"1px solid #141414",display:"flex",justifyContent:"space-around",alignItems:"center",padding:"7px 0 14px",zIndex:100}}>
      {NAV.map(n=>(
        <button key={n.id} className={`nb ${screen===n.id?"on":""}`} onClick={()=>setScreen(n.id)}>
          <span style={{fontSize:17,lineHeight:1,position:"relative"}}>
            {n.icon}
            {n.id==="messages"&&unread>0&&<span style={{position:"absolute",top:-4,right:-6,width:14,height:14,borderRadius:"50%",background:"#B8D400",color:"#0A0A0A",fontSize:8,fontWeight:900,display:"flex",alignItems:"center",justifyContent:"center"}}>{unread}</span>}
          </span>
          <span>{n.label}</span>
        </button>
      ))}
    </div>
  </div>;
}
